const { chromium } = require(PKG + '/node_modules/@playwright/test');
const AxeBuilder = require(PKG + '/node_modules/@axe-core/playwright').default;
const SP = process.argv[2];
const states = {
  pass: ['17.5', '23', '70'],
  fail: ['17.49', '25', '70'],
};
(async () => {
  const browser = await chromium.launch();
  for (const scheme of ['light', 'dark']) {
    for (const width of [375, 1280]) {
      const ctx = await browser.newContext({ viewport: { width, height: 900 }, colorScheme: scheme });
      const page = await ctx.newPage();
      const msgs = [];
      page.on('console', (m) => msgs.push(m.type() + ': ' + m.text()));
      page.on('pageerror', (e) => msgs.push('pageerror: ' + e.message));
      await page.goto('http://127.0.0.1:4173/');
      const measure = async () => page.evaluate(() => ({
        card: document.querySelector('.card').getBoundingClientRect().height,
        btnTop: document.querySelector('.btn').getBoundingClientRect().top,
        scrollW: document.documentElement.scrollWidth,
      }));
      const idle = await measure();
      for (const [name, [e, t, p]] of Object.entries(states)) {
        await page.fill('#pass-mark', p);
        await page.fill('#total', t);
        await page.fill('#earned', e);
        await page.locator('.verdict').waitFor();
        await page.locator('#earned').blur();
        const m = await measure();
        const axe = await new AxeBuilder({ page }).withTags(['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa']).analyze();
